content:
Below is a clean Terraform module layout that provisions:

- **S3 bucket** with versioning, encryption, and public access block
- **RDS PostgreSQL** with deletion protection, backups, and private-only access
- **IAM role for service accounts** with least-privilege policy attachment
- **dev/prod support** via `tfvars` or Terraform workspaces

I’m keeping it modular and practical.

---

# Suggested structure

```text
terraform/
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    ├── s3_bucket/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds_postgres/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam_service_account_role/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

# Root module

## `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

---

## `variables.tf`

```hcl
variable "aws_region" {
  type        = string
  description = "AWS region"
}

variable "environment" {
  type        = string
  description = "Environment name, e.g. dev or prod"
}

variable "name_prefix" {
  type        = string
  description = "Prefix for resource naming"
}

variable "bucket_name" {
  type        = string
  description = "S3 bucket name"
}

variable "enable_bucket_replication" {
  type        = bool
  description = "Enable cross-region replication for prod"
  default     = false
}

variable "replication_destination_bucket_arn" {
  type        = string
  description = "Destination bucket ARN for replication"
  default     = null
}

variable "db_name" {
  type        = string
  description = "PostgreSQL database name"
}

variable "db_username" {
  type        = string
  description = "PostgreSQL master username"
  sensitive   = true
}

variable "db_password" {
  type        = string
  description = "PostgreSQL master password"
  sensitive   = true
}

variable "db_instance_class" {
  type        = string
  description = "RDS instance class"
}

variable "db_allocated_storage" {
  type        = number
  description = "Allocated DB storage in GB"
  default     = 20
}

variable "db_multi_az" {
  type        = bool
  description = "Enable Multi-AZ for RDS"
  default     = false
}

variable "db_storage_encrypted" {
  type        = bool
  description = "Encrypt RDS storage"
  default     = true
}

variable "db_backup_retention_period" {
  type        = number
  description = "Backup retention days"
  default     = 7
}

variable "db_subnet_ids" {
  type        = list(string)
  description = "Private subnet IDs for RDS subnet group"
}

variable "vpc_security_group_ids" {
  type        = list(string)
  description = "Security groups for RDS"
}

variable "service_account_role_name" {
  type        = string
  description = "IAM role name for service account"
}

variable "oidc_provider_arn" {
  type        = string
  description = "OIDC provider ARN for EKS IRSA trust"
}

variable "oidc_provider_url" {
  type        = string
  description = "OIDC provider URL without https://"
}

variable "k8s_namespace" {
  type        = string
  description = "Kubernetes namespace of the service account"
}

variable "k8s_service_account_name" {
  type        = string
  description = "Kubernetes service account name"
}
```

---

## `main.tf`

```hcl
provider "aws" {
  region = var.aws_region
}

module "s3_bucket" {
  source = "./modules/s3_bucket"

  bucket_name                          = var.bucket_name
  enable_bucket_replication            = var.enable_bucket_replication
  replication_destination_bucket_arn   = var.replication_destination_bucket_arn
  environment                          = var.environment
}

module "rds_postgres" {
  source = "./modules/rds_postgres"

  identifier                = "${var.name_prefix}-${var.environment}-postgres"
  db_name                   = var.db_name
  username                  = var.db_username
  password                  = var.db_password
  instance_class            = var.db_instance_class
  allocated_storage         = var.db_allocated_storage
  multi_az                  = var.db_multi_az
  storage_encrypted         = var.db_storage_encrypted
  backup_retention_period   = var.db_backup_retention_period
  db_subnet_ids             = var.db_subnet_ids
  vpc_security_group_ids    = var.vpc_security_group_ids
  publicly_accessible       = false
  deletion_protection       = true
}

module "iam_service_account_role" {
  source = "./modules/iam_service_account_role"

  role_name                  = var.service_account_role_name
  oidc_provider_arn          = var.oidc_provider_arn
  oidc_provider_url          = var.oidc_provider_url
  k8s_namespace              = var.k8s_namespace
  k8s_service_account_name   = var.k8s_service_account_name
  bucket_arn                 = module.s3_bucket.bucket_arn
}
```

